const lockSubmittedCartItems = `-- name: LockSubmittedCartItems :many
SELECT ci.id, ci.user_id, ci.variant_id, ci.quantity, ci.selected,
       ci.snapshot_brand_name, ci.snapshot_product_name, ci.snapshot_model,
       ci.snapshot_image_url, ci.snapshot_options::text AS snapshot_options,
       v.product_id, p.active AS product_active, v.active AS variant_active,
       v.price_vnd::text AS price_vnd, v.stock_quantity,
       p.brand AS brand_name, p.name AS product_name, p.model,
       COALESCE((SELECT pi.url FROM product_images pi WHERE pi.product_id = p.id ORDER BY pi.position, pi.id LIMIT 1), '')::text AS image_url,
       COALESCE((SELECT jsonb_agg(jsonb_build_object('groupLabel', g.label, 'valueLabel', ov.label) ORDER BY g.position, g.id)
                 FROM variant_option_values vov JOIN product_option_groups g ON g.id = vov.group_id
                 JOIN product_option_values ov ON ov.id = vov.option_value_id
                 WHERE vov.variant_id = v.id), '[]'::jsonb)::text AS options
FROM cart_items ci
JOIN product_variants v ON v.id = ci.variant_id
JOIN products p ON p.id = v.product_id
WHERE ci.user_id = $1 AND v.id = ANY($2::uuid[])
ORDER BY ci.created_at, ci.id
FOR UPDATE OF ci, v
`

type LockSubmittedCartItemsParams struct {
	UserID     string
	VariantIds []string
}

type LockSubmittedCartItemsRow struct {
	ID                  string
	UserID              string
	VariantID           string
	Quantity            int64
	Selected            bool
	SnapshotBrandName   string
	SnapshotProductName string
	SnapshotModel       string
	SnapshotImageUrl    string
	SnapshotOptions     string
	ProductID           string
	ProductActive       bool
	VariantActive       bool
	PriceVnd            string
	StockQuantity       int64
	BrandName           string
	ProductName         string
	Model               string
	ImageUrl            string
	Options             string
}

func (q *Queries) LockSubmittedCartItems(ctx context.Context, arg LockSubmittedCartItemsParams) ([]LockSubmittedCartItemsRow, error) {
	rows, err := q.db.Query(ctx, lockSubmittedCartItems, arg.UserID, arg.VariantIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LockSubmittedCartItemsRow
	for rows.Next() {
		var i LockSubmittedCartItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.VariantID,
			&i.Quantity,
			&i.Selected,
			&i.SnapshotBrandName,
			&i.SnapshotProductName,
			&i.SnapshotModel,
			&i.SnapshotImageUrl,
			&i.SnapshotOptions,
			&i.ProductID,
			&i.ProductActive,
			&i.VariantActive,
			&i.PriceVnd,
			&i.StockQuantity,
			&i.BrandName,
			&i.ProductName,
			&i.Model,
			&i.ImageUrl,
			&i.Options,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

